mapper.select:
SELECT id, role, content, attachments_json AS attachmentsJson
FROM chat_messages
WHERE session_id = #{sessionId}
ORDER BY id DESC
LIMIT #{limit}

mapper.update:
UPDATE chat_messages
SET generation_status = 'FAILED', failure_code = #{failureCode}
WHERE id = #{messageId} AND session_id = #{sessionId} AND role = 'user'

